// Deployed as the body of each proxy Worker. KEY and TG are prepended to this source.
async function tgRelayMain(req) {
  const u = new URL(req.url);
  if (u.pathname === '/healthz') return new Response('ok', { headers: { 'content-type': 'text/plain' } });
  const pre = '/' + KEY;
  if (u.pathname !== pre && !u.pathname.startsWith(pre + '/')) return new Response('Not found', { status: 404 });
  const rest = u.pathname.slice(pre.length) || '/';
  const target = new URL(rest + u.search, TG);
  const h = new Headers(req.headers);
  h.set('host', new URL(TG).host);
  h.set('origin', TG);
  h.set('referer', TG + '/');
  h.delete('cf-connecting-ip');
  if ((req.headers.get('upgrade') || '').toLowerCase() === 'websocket') return fetch(target, { headers: h });
  const r = await fetch(target, { method: req.method, headers: h, body: (req.method === 'GET' || req.method === 'HEAD') ? undefined : req.body, redirect: 'manual' });
  const out = new Headers(r.headers);
  out.delete('content-security-policy'); out.delete('content-security-policy-report-only');
  out.delete('x-frame-options'); out.delete('strict-transport-security');
  const cookies = typeof r.headers.getSetCookie === 'function' ? r.headers.getSetCookie() : [];
  out.delete('set-cookie');
  for (const c of cookies) out.append('set-cookie', c.replace(/;\s*domain=[^;]*/i, ''));
  const base = u.origin + pre;
  const loc = out.get('location'); if (loc) out.set('location', loc.split(TG).join(base));
  const ct = out.get('content-type') || '';
  if (/text|javascript|json/i.test(ct)) {
    const t = (await r.text()).split(TG).join(base);
    out.delete('content-length');
    return new Response(t, { status: r.status, headers: out });
  }
  return new Response(r.body, { status: r.status, headers: out });
}

