const TG_NAME = /^[a-zA-Z0-9_-]{1,40}$/;
const faNum = (t) => String(t || '').replace(/[\u06F0-\u06F9]/g, (c) => String(c.charCodeAt(0) - 1776)).replace(/[\u0660-\u0669]/g, (c) => String(c.charCodeAt(0) - 1632)).trim();
const tgStyle = (d) => /^a:(del|delok|regen|regenok)/.test(d) ? 'danger' : /^(c:new)/.test(d) ? 'success' : /^(m|c:list|c:stats|c:find|c:expiring|c:help)/.test(d) ? 'primary' : undefined;
const tgKb = (rows) => ({ inline_keyboard: rows.map((r) => r.map(([text, data]) => ({ text, callback_data: data, style: tgStyle(data) }))) });
const TG_BANNER_B64 = '';
let TG_FID = null;
async function tgPhoto(token, chat, caption, rows) {
  const cap = String(caption || '').slice(0, 1000);
  if (TG_FID) { const r = await tgApi(token, 'sendPhoto', { chat_id: chat, photo: TG_FID, caption: cap, reply_markup: rows ? tgKb(rows) : undefined }); if (r.ok) return r; TG_FID = null; }
  try {
    const fd = new FormData(); fd.append('chat_id', String(chat)); fd.append('caption', cap);
    if (rows) fd.append('reply_markup', JSON.stringify(tgKb(rows)));
    fd.append('photo', new Blob([Uint8Array.from(atob(TG_BANNER_B64), (c) => c.charCodeAt(0))], { type: 'image/jpeg' }), 'vex.jpg');
    const j = await (await fetch('https://api.telegram.org/bot' + token + '/sendPhoto', { method: 'POST', body: fd })).json();
    if (j.ok && j.result && j.result.photo) TG_FID = j.result.photo[j.result.photo.length - 1].file_id;
    return j;
  } catch (e) { return { ok: false }; }
}
const tgMain = [[['ساخت سرویس', 'c:new'], ['لیست سرویس‌ها', 'c:list:0']], [['جستجو', 'c:find'], ['رو به اتمام', 'c:expiring']], [['آمار', 'c:stats'], ['روشن/خاموش کل', 'c:gtog']], [['راهنما', 'c:help']]];
const TG_HELP = 'راهنمای پنل Vex\n\nساخت سرویس: با پروفایل آماده یا حالت دلخواه.\nلیست و جستجو: مدیریت هر سرویس با دکمه‌ها.\nرو به اتمام: سرویس‌هایی که کمتر از ۳ روز یا ۱۰٪ حجم دارند.\nآمار: تعداد سرویس‌ها، آنلاین‌ها و ترافیک امروز.\nروشن/خاموش کل: قطع یا وصل همه سرویس‌ها.';
async function tgApi(token, method, body) { try { const r = await fetch('https://api.telegram.org/bot' + token + '/' + method, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }); return await r.json(); } catch (e) { return { ok: false }; } }
const tgSend = (token, chat, text, rows) => (rows === tgMain ? tgPhoto(token, chat, text, rows) : tgApi(token, 'sendMessage', { chat_id: chat, text: text, reply_markup: rows ? tgKb(rows) : undefined }));
const tgGetState = async (env) => parseJ(await getSet(env, 'tg_state', ''), null);
const tgSetState = (env, s) => setSet(env, 'tg_state', s ? JSON.stringify(s) : '');
async function tgCall(env, url, act, body) {
  const t = hex(24);
  await env.DB.prepare('INSERT INTO sessions(t,exp) VALUES(?,?)').bind(t, now() + 60).run();
  try {
    const req = new Request(url.origin + '/tg', { method: 'POST', headers: { 'X-Req': '1', 'X-Panel-Session': t, 'Content-Type': 'application/json', 'CF-Connecting-IP': 'telegram' }, body: JSON.stringify(body || {}) });
    return await (await panelApi(req, env, act, url)).json();
  } catch (e) { return { ok: false, error: 'خطا در انجام عملیات' }; }
  finally { await env.DB.prepare('DELETE FROM sessions WHERE t=?').bind(t).run(); }
}
const tgNum = (x) => { const v = Number(faNum(x)); return Number.isFinite(v) && v >= 0 ? v : NaN; };
async function tgView(env, url, token, chat, id) {
  const u = await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(id).first();
  if (!u) return tgSend(token, chat, 'سرویس پیدا نشد.', tgMain);
  const gbs = (b) => ((Number(b) || 0) / 1073741824).toFixed(2) + ' GB';
  const lim = Number(u.limit_bytes) || 0, exp = Number(u.expire) > 0 ? Math.max(0, Math.ceil((Number(u.expire) - now()) / 86400)) + ' روز مانده' : (Number(u.start_mode) === 1 && !Number(u.first_conn) ? 'از اولین اتصال' : 'نامحدود');
  const on = Number(u.active) === 1;
  const workerHost = String(env.WORKER_HOST || url.host), pagesHost = String(env.PAGES_HOST || url.host);
  const txt = 'سرویس: ' + u.name + '\nوضعیت: ' + (on ? 'فعال' : 'غیرفعال') + '\nمصرف: ' + gbs(u.used) + ' از ' + (lim ? gbs(lim) : 'نامحدود') + '\nاعتبار: ' + exp + '\nدستگاه: ' + (Number(u.max_ips) || 'نامحدود') + '\nاشتراک Worker: https://' + workerHost + '/sub/' + u.token + '\nاشتراک Pages: https://' + pagesHost + '/sub/' + u.token;
  return tgSend(token, chat, txt, [
    [[on ? 'غیرفعال کردن' : 'فعال کردن', 'a:tog:' + id], ['لینک کانفیگ', 'a:link:' + id]],
    [['افزودن حجم', 'a:addgb:' + id], ['کم کردن حجم', 'a:subgb:' + id]],
    [['تنظیم حجم دقیق', 'a:setgb:' + id], ['افزودن روز', 'a:adddays:' + id]],
    [['ریست مصرف', 'a:reset:' + id], ['تعداد دستگاه', 'a:dev:' + id]],
    [['تغییر نام', 'a:name:' + id], ['UUID جدید', 'a:regen:' + id]],
    [['حذف سرویس', 'a:del:' + id], ['لیست سرویس‌ها', 'c:list:0']],
  ]);
}
async function tgCreate(env, url, token, chat, p) {
  const r = await tgCall(env, url, 'create', { name: p.name, gb: p.gb, days: p.days, max_ips: p.devices, speed: p.speed, protos: ['vless'], ports: [443], with_direct: 1, block_ads: 1 });
  if (!r.ok) return tgSend(token, chat, 'ساخت سرویس انجام نشد: ' + (r.error || ''), tgMain);
  const u = r.users[0], row = await env.DB.prepare('SELECT id FROM users WHERE token=?').bind(u.token).first();
  return tgSend(token, chat, 'سرویس ' + u.name + ' ساخته شد.\nاشتراک Worker:\n' + (u.worker_sub || u.sub) + '\n\nاشتراک Pages:\n' + (u.pages_sub || u.sub), [[['مدیریت این سرویس', 'u:' + (row ? row.id : 0)]], [['منو', 'm']]]);
}
async function tgList(env, token, chat, page) {
  const per = 8, total = Number((await env.DB.prepare('SELECT COUNT(*) c FROM users').first()).c) || 0;
  const rs = await env.DB.prepare('SELECT id,name,active FROM users ORDER BY id DESC LIMIT ? OFFSET ?').bind(per, page * per).all();
  const rows = (rs.results || []).map((x) => [[(Number(x.active) === 1 ? '' : '[غیرفعال] ') + x.name, 'u:' + x.id]]);
  const nav = []; if (page > 0) nav.push(['قبلی', 'c:list:' + (page - 1)]); if ((page + 1) * per < total) nav.push(['بعدی', 'c:list:' + (page + 1)]);
  if (nav.length) rows.push(nav);
  rows.push([['منو', 'm']]);
  return tgSend(token, chat, total ? 'سرویس‌ها (' + total + '):' : 'هنوز سرویسی ساخته نشده.', rows);
}
async function tgStats(env, token, chat) {
  const c = await env.DB.prepare('SELECT COUNT(*) c, SUM(CASE WHEN active=1 THEN 1 ELSE 0 END) a, SUM(CASE WHEN active=1 AND last>? THEN 1 ELSE 0 END) o FROM users').bind(now() - 90).first();
  let d = null; try { d = await env.DB.prepare('SELECT conns,bytes FROM daily WHERE day=?').bind(new Date().toISOString().slice(0, 10)).first(); } catch (e) { d = null; }
  return tgSend(token, chat, 'آمار پنل Vex\n\nکل سرویس‌ها: ' + (c.c || 0) + '\nفعال: ' + (c.a || 0) + '\nآنلاین الان: ' + (c.o || 0) + '\nاتصال امروز: ' + ((d && d.conns) || 0) + '\nترافیک امروز: ' + ((Number(d && d.bytes) || 0) / 1073741824).toFixed(2) + ' GB', tgMain);
}
async function tgExpiring(env, token, chat) {
  const rs = await env.DB.prepare('SELECT id,name FROM users WHERE active=1 AND ((expire>0 AND expire<=?) OR (limit_bytes>0 AND used>=limit_bytes*0.9)) ORDER BY expire ASC LIMIT 15').bind(now() + 3 * 86400).all();
  const rows = (rs.results || []).map((x) => [[x.name, 'u:' + x.id]]); rows.push([['منو', 'm']]);
  return tgSend(token, chat, rows.length > 1 ? 'سرویس‌های نزدیک به اتمام اعتبار یا حجم:' : 'هیچ سرویسی نزدیک به اتمام نیست.', rows);
}
const TG_ACT_PROMPT = { addgb: 'حجم برای افزودن (GB) را بفرست', subgb: 'حجم برای کم کردن (GB) را بفرست', setgb: 'حجم دقیق (GB) را بفرست؛ ۰ = نامحدود', adddays: 'چند روز اضافه شود؟', dev: 'حداکثر تعداد دستگاه را بفرست؛ ۰ = نامحدود', name: 'نام جدید را بفرست (انگلیسی، عدد، - و _)' };
const TG_ACT_KEY = { addgb: 'add_gb', subgb: 'sub_gb', setgb: 'gb', adddays: 'add_days', dev: 'max_ips' };
async function tgCb(env, url, token, chat, d) {
  const [k, a, x] = d.split(':');
  if (d === 'm') { await tgSetState(env, null); return tgSend(token, chat, 'پنل مدیریت', tgMain); }
  if (k === 'c') {
    if (a === 'new') { await tgSetState(env, { s: 'name' }); return tgSend(token, chat, 'نام سرویس را بفرست (انگلیسی، عدد، - و _).'); }
    if (a === 'list') return tgList(env, token, chat, Number(x) || 0);
    if (a === 'stats') return tgStats(env, token, chat);
    if (a === 'find') { await tgSetState(env, { s: 'find' }); return tgSend(token, chat, 'بخشی از نام سرویس را بفرست.'); }
    if (a === 'expiring') return tgExpiring(env, token, chat);
    if (a === 'help') return tgSend(token, chat, TG_HELP, [[['منو', 'm']]]);
    if (a === 'gtog') { const cur = (await getSet(env, 'global_servers_enabled', '1')) === '1'; const r = await tgCall(env, url, 'service_toggle', { enabled: !cur }); return tgSend(token, chat, 'سرویس‌ها ' + (r.enabled ? 'روشن' : 'خاموش') + ' شدند.', tgMain); }
  }
  if (k === 'u') { await tgSetState(env, null); return tgView(env, url, token, chat, Number(a)); }
  if (k === 'a') {
    const id = Number(x) || 0; await tgSetState(env, null);
    if (a === 'tog') { const u = await env.DB.prepare('SELECT active FROM users WHERE id=?').bind(id).first(); if (!u) return; await tgCall(env, url, 'edit', { id, active: Number(u.active) !== 1 }); return tgView(env, url, token, chat, id); }
    if (a === 'link') { const r = await tgCall(env, url, 'links', { id }); if (!r.ok) return tgSend(token, chat, 'سرویس پیدا نشد.'); return tgSend(token, chat, ('اشتراک Worker:\n' + (r.worker_sub || r.sub) + '\n\nاشتراک Pages:\n' + (r.pages_sub || r.sub) + '\n\n' + (r.links || []).map((l) => l.link).join('\n')).slice(0, 3900), [[['برگشت', 'u:' + id]]]); }
    if (a === 'reset') { await tgCall(env, url, 'edit', { id, reset: 1 }); return tgView(env, url, token, chat, id); }
    if (a === 'regen') return tgSend(token, chat, 'UUID جدید ساخته شود؟ کانفیگ قبلی کار نمی‌کند.', [[['بله', 'a:regenok:' + id], ['انصراف', 'u:' + id]]]);
    if (a === 'regenok') { await tgCall(env, url, 'edit', { id, regen: 1 }); return tgView(env, url, token, chat, id); }
    if (a === 'del') return tgSend(token, chat, 'این سرویس حذف شود؟ این کار برگشت ندارد.', [[['بله، حذف کن', 'a:delok:' + id], ['انصراف', 'u:' + id]]]);
    if (a === 'delok') { await tgCall(env, url, 'del', { id }); return tgSend(token, chat, 'سرویس حذف شد.', tgMain); }
    if (TG_ACT_PROMPT[a]) { await tgSetState(env, { s: 'act', a: a, id: id }); return tgSend(token, chat, TG_ACT_PROMPT[a]); }
  }
}
async function tgText(env, url, token, chat, text) {
  if (/^\/(start|menu)/.test(text) || text === 'منو') { await tgSetState(env, null); return tgSend(token, chat, 'پنل مدیریت', tgMain); }
  const s = await tgGetState(env);
  if (!s) return tgSend(token, chat, 'از دکمه‌های زیر استفاده کن.', tgMain);
  if (s.s === 'name') {
    if (!TG_NAME.test(text)) return tgSend(token, chat, 'نام نامعتبر است؛ فقط انگلیسی، عدد، - و _ (حداکثر ۴۰ کاراکتر).');
    await tgSetState(env, { s: 'cgb', name: text });
    return tgSend(token, chat, 'حجم به گیگابایت را بفرست؛ ۰ = نامحدود');
  }
  if (s.s === 'cgb') {
    const v = tgNum(text); if (isNaN(v)) return tgSend(token, chat, 'عدد معتبر بفرست.');
    await tgSetState(env, { s: 'cdays', name: s.name, gb: v }); return tgSend(token, chat, 'مدت اعتبار (روز) را بفرست؛ ۰ = نامحدود');
  }
  if (s.s === 'cdays') {
    const v = tgNum(text); if (isNaN(v)) return tgSend(token, chat, 'عدد معتبر بفرست.');
    await tgSetState(env, { s: 'cdev', name: s.name, gb: s.gb, days: v });
    return tgSend(token, chat, 'تعداد دستگاه همزمان را بفرست؛ ۰ = نامحدود');
  }
  if (s.s === 'cdev') {
    const v = tgNum(text); if (isNaN(v)) return tgSend(token, chat, 'عدد معتبر بفرست.');
    await tgSetState(env, { s: 'cspeed', name: s.name, gb: s.gb, days: s.days, devices: v });
    return tgSend(token, chat, 'سرعت به Mbps را بفرست؛ ۰ = نامحدود');
  }
  if (s.s === 'cspeed') {
    const v = tgNum(text); if (isNaN(v)) return tgSend(token, chat, 'عدد معتبر بفرست.');
    await tgSetState(env, null);
    return tgCreate(env, url, token, chat, { name: s.name, gb: s.gb, days: s.days, devices: s.devices, speed: v });
  }
  if (s.s === 'find') {
    await tgSetState(env, null);
    const rs = await env.DB.prepare('SELECT id,name,active FROM users WHERE name LIKE ? ORDER BY id DESC LIMIT 10').bind('%' + text.replace(/[%_]/g, '') + '%').all();
    const rows = (rs.results || []).map((x) => [[(Number(x.active) === 1 ? '' : '[غیرفعال] ') + x.name, 'u:' + x.id]]); rows.push([['منو', 'm']]);
    return tgSend(token, chat, rows.length > 1 ? 'نتیجه جستجو:' : 'موردی پیدا نشد.', rows);
  }
  if (s.s === 'act') {
    await tgSetState(env, null);
    let body;
    if (s.a === 'name') { if (!TG_NAME.test(text)) return tgSend(token, chat, 'نام نامعتبر است.'); body = { id: s.id, name: text }; }
    else { const v = tgNum(text); if (isNaN(v)) return tgSend(token, chat, 'عدد معتبر بفرست.'); body = { id: s.id }; body[TG_ACT_KEY[s.a]] = v; }
    const r = await tgCall(env, url, 'edit', body);
    if (!r.ok) return tgSend(token, chat, 'انجام نشد: ' + (r.error || ''), tgMain);
    return tgView(env, url, token, chat, s.id);
  }
  return tgSend(token, chat, 'از دکمه‌های زیر استفاده کن.', tgMain);
}
async function tgUpdate(env, url, token, upd) {
  const cq = upd.callback_query, m = upd.message || upd.edited_message;
  const from = (cq ? cq.from : (m && m.from)) || {};
  const admin = String((await getSet(env, 'tg_admin', '')) || '');
  if (!admin || String(from.id || '') !== admin) return;
  if (cq) { await tgApi(token, 'answerCallbackQuery', { callback_query_id: cq.id }); return tgCb(env, url, token, cq.message.chat.id, String(cq.data || '')); }
  if (m && m.chat) return tgText(env, url, token, m.chat.id, String(m.text || '').trim());
}

async function adminNotify(env, text) {
  try {
    const r = await env.DB.prepare('SELECT token_enc,enabled FROM telegram_bot WHERE id=1').first();
    const admin = String((await getSet(env, 'tg_admin', '')) || '');
    if (!r || Number(r.enabled) !== 1 || !admin) return false;
    const token = await secretDec(env, r.token_enc || '');
    if (!token) return false;
    const res = await tgApi(token, 'sendMessage', { chat_id: admin, text: String(text).slice(0, 4000) });
    return !!(res && res.ok);
  } catch (e) { return false; }
}
async function runChecks(env) {
  await init(env);
  const t = now(), day = 86400, msgs = [];
  const users = ((await env.DB.prepare('SELECT id,name,limit_bytes,used,expire,active,proxy_ip FROM users').all()).results) || [];
  const flag = async (k, on) => {
    const cur = await getSet(env, k, '');
    if (on) { if (cur !== '1') { await setSet(env, k, '1'); return true; } return false; }
    if (cur) await setSet(env, k, '');
    return false;
  };
  for (const u of users) {
    if (!Number(u.active)) continue;
    const lim = Number(u.limit_bytes) || 0, used = Number(u.used) || 0, exp = Number(u.expire) || 0;
    if (await flag('warn:' + u.id + ':vol', lim > 0 && used >= lim * 0.8))
      msgs.push('⚠️ حجم «' + u.name + '» به ' + Math.round((used / lim) * 100) + '٪ رسیده است');
    if (await flag('warn:' + u.id + ':exp', exp > 0 && exp - t < 2 * day))
      msgs.push(exp <= t ? '⛔ «' + u.name + '» منقضی شده است' : '⏳ «' + u.name + '» کمتر از ۲ روز تا انقضا دارد');
  }
  const ips = [...new Set(users.map((u) => u.proxy_ip).filter(Boolean))].slice(0, 40);
  const prevH = parseJ(await getSet(env, 'proxy_health', '{}'), {}), nextH = {};
  for (let i = 0; i < ips.length; i += 5) {
    const part = ips.slice(i, i + 5);
    const res = await Promise.all(part.map((ip) => quickProbe(ip)));
    part.forEach((ip, j) => {
      const ok = !!res[j], pf = (prevH[ip] && Number(prevH[ip].fails)) || 0;
      const fails = ok ? 0 : pf + 1;
      const count = users.filter((x) => x.proxy_ip === ip).length;
      if (!ok && fails === 2) msgs.push('🔴 Proxy IP ' + ip + ' در دسترس نیست؛ ' + count + ' کاربر تحت تاثیرند');
      if (ok && pf >= 2) msgs.push('🟢 Proxy IP ' + ip + ' دوباره در دسترس است');
      nextH[ip] = { ok, fails, t };
    });
  }
  await setSet(env, 'proxy_health', JSON.stringify(nextH));
  if (msgs.length) await adminNotify(env, msgs.join('\n'));
  return { users: users.length, proxies: ips.length, alerts: msgs.length, health: nextH };
}

async function resolveDoH(domain) {
try {
const r = await fetch('https://cloudflare-dns.com/dns-query?name=' + encodeURIComponent(domain) + '&type=A', { headers: { accept: 'application/dns-json' } });
const j = await r.json();
return (j.Answer || []).filter((a) => a.type === 1).map((a) => a.data);
} catch (e) { return []; }
}
async function geoLookupBatch(ipList) {
const out = [];
for (let i = 0; i < ipList.length; i += 100) {
const batch = ipList.slice(i, i + 100);
try {
const r = await fetch('http://ip-api.com/batch?fields=query,city,country,countryCode,isp,status', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(batch) });
const data = await r.json();
for (const item of data) {
if (item.status === 'success') out.push({ ip: item.query, city: item.city || '', country: item.country || '', countryCode: item.countryCode || '', isp: item.isp || '' });
else out.push({ ip: item.query, city: '', country: '', countryCode: '', isp: '' });
}
} catch (e) { for (const ip of batch) out.push({ ip, city: '', country: '', countryCode: '', isp: '' }); }
}
return out;
}
