const GEO_OVERRIDE = { IL: { country: 'Israel', city: 'Tel Aviv', ips: ['185.162.124.28'] } };
const GEO = new Map();
async function geoPool(env) {
  const hit = GEO.get('p');
  if (hit && hit.t > Date.now()) return hit.items;
  const cfg = parseAddrList(await getSetC(env, 'proxy_ips'), 200);
  const src = [...new Set([...cfg, ...BUILTIN_PROXY_IPS, ...(cfg.length ? [] : ['bpb.yousef.isegaro.com'])])];
  const ips = [];
  for (const d of src) {
    if (/^[0-9]{1,3}(?:\.[0-9]{1,3}){3}$/.test(d)) ips.push(d);
    else ips.push(...(await resolveDoH(d)));
  }
  const uniq = [...new Set(ips)].slice(0, 600);
  const items = (await geoLookupBatch(uniq)).filter((x) => x.countryCode && !GEO_OVERRIDE[x.countryCode]);
  for (const cc of Object.keys(GEO_OVERRIDE)) for (const ip of GEO_OVERRIDE[cc].ips) items.push({ ip, countryCode: cc, country: GEO_OVERRIDE[cc].country, city: GEO_OVERRIDE[cc].city, isp: 'manual' });
  GEO.set('p', { t: Date.now() + 10 * 60000, items });
  return items;
}
async function quickProbe(ip) {
  try {
    const sock = connect({ hostname: ip, port: 443 });
    const w = sock.writable.getWriter();
    await w.write(new TextEncoder().encode('GET /__down?bytes=5000 HTTP/1.1\r\nHost: speed.cloudflare.com\r\nConnection: close\r\n\r\n'));
    w.releaseLock();
    const rd = sock.readable.getReader();
    const { value, done } = await Promise.race([rd.read(), new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 3000))]);
    rd.releaseLock();
    await sock.close().catch(() => {});
    if (done || !value) return false;
    const txt = new TextDecoder().decode(value);
    return /^HTTP\/1\.[01] 400/.test(txt) && /cf-ray:/i.test(txt);
  } catch (e) { return false; }
}
const HPROBE = new Map();
async function healthy(ip) {
  const h = HPROBE.get(ip);
  if (h && h.t > Date.now()) return h.ok;
  const ok = await quickProbe(ip);
  HPROBE.set(ip, { ok, t: Date.now() + 5 * 60000 });
  return ok;
}
async function pickProxyByCountry(env, cc) {
  const list = (await geoPool(env)).filter((x) => x.countryCode === cc).map((x) => x.ip);
  for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; }
  const cand = list.slice(0, 12);
  for (let i = 0; i < cand.length; i += 3) {
    const res = await Promise.all(cand.slice(i, i + 3).map(healthy));
    const idx = res.indexOf(true);
    if (idx >= 0) return cand[i + idx];
  }
  return '';
}
async function testProxyIP(address) {
const TIMEOUT_MS = 5000, ATTEMPTS = 5;
const check = async () => {
const start = Date.now();
try {
const socket = connect({ hostname: address, port: 443 });
const writer = socket.writable.getWriter();
await writer.write(new TextEncoder().encode('GET /__down?bytes=5000 HTTP/1.1\r\nHost: speed.cloudflare.com\r\nConnection: close\r\n\r\n'));
writer.releaseLock();
const reader = socket.readable.getReader();
const timeout = new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), TIMEOUT_MS));
const { value, done } = await Promise.race([reader.read(), timeout]);
reader.releaseLock();
await socket.close().catch(() => {});
if (done || !value) return { ok: false, elapsedMs: Date.now() - start };
const response = new TextDecoder().decode(value);
const isOk = /^HTTP\/1\.[01] 400/.test(response);
const hasCfRay = /cf-ray:/i.test(response);
return { ok: isOk && hasCfRay, elapsedMs: Date.now() - start };
} catch (e) { return { ok: false, elapsedMs: Date.now() - start }; }
};
const attempts = await Promise.all(Array.from({ length: ATTEMPTS }, (_, i) => check().then((r) => ({ attempt: i + 1, ...r }))));
const successes = attempts.filter((a) => a.ok);
const avgLatencyMs = successes.length ? Math.round(successes.reduce((s, a) => s + a.elapsedMs, 0) / successes.length) : null;
return { successRate: successes.length + '/' + ATTEMPTS, avgLatencyMs, attempts };
}
